      const drawS = () => { let cells = SWORD[key]; if (Math.cos(st.ang) < 0) cells = cells.map(([x, y, c]) => [x, -y, c]); for (const [x, y, c] of rotCells(cells, st.ang)) { if (hy + y > ks) continue; ctx.fillStyle = P[c]; ctx.fillRect((hx + x) * C, (hy + y) * C, C, C); } };
