  function clampIn(b) { b.x = clamp(b.x, A.x0 + 24, A.x1 - 24); b.y = clamp(b.y, A.y0 + 20, A.y1 - 10); }

  // ---------------------------------------------------------------- v3.58 쓰러짐 → 그 자리에서 천천히 죽어감 (숨이 느려지고 몸이 처지며 피가 고임) → 멈춤 → 잠시 뒤 일어서며 말 (컷신) → 변신 → 2페이즈
  const T_FALL = 0.35, T_DIE = 2.0, T_STILL = 0.8, RB = 0.6; // v3.59 전환을 짧게 (죽어감 3.6 → 2.0 · 멈춤 1.8 → 0.8 · 일어서며 말 한 마디 0.95 → 0.6초)
  function fall(b) {
    const C = b.cb; C.ph = 'fall'; C.t0 = time; b.state = 'fall'; b.hp = 1; C.hpLock = 1; C.dash = null; C.mv = null; cancelTele(b); sfx('hurt', 0.6); shake(6); burst(b.x, b.y - 14, '#8a1418', 20);
  }
  function fallTick(b, dt) {
    const C = b.cb, t = time - C.t0;
    if (C.ph === 'fall') { if (t > T_FALL) { C.ph = 'dying'; C.t0 = time; C.br = 0; } return; }
    if (C.ph === 'dying') { // 숨이 점점 느려짐 (들썩이는 간격 0.5 → 1.4초) · 피가 고이다 멎음
      const k = Math.min(1, t / T_DIE); C.br += dt / (0.45 + 0.75 * k);
      if (Math.random() < dt * 7 * (1 - k)) BLOOD.push({ x: b.x + rand(-10, 10), y: b.y + rand(-2, 4), s: pick([2, 4, 4, 6]), t0: time });
      if (t > T_DIE) { C.ph = 'still'; C.t0 = time; } return; }
    if (C.ph === 'still') { if (t > T_STILL) { C.ph = 'rise'; C.t0 = time; setMood('cultBoss2'); /* v3.83 일어서는 순간 2페이즈 곡으로 */ cancelTele(b); try { CINE.focus(Math.round((b.x + G.player.x) / 2), Math.round((b.y - 40 + G.player.y - 12) / 2)); } catch (x) { /* 시네마 없음 */ } } return; } // 멈춤 → 잠시 뒤 2페이즈 진입 컷신 (말은 저절로)
    if (C.ph === 'rise') { // 일어서며 알 수 없는 말: {말}, {말}, {말}{말}{말}
      if (!C.said) { C.said = true; say(glyWord(2), 0.3, RB); say(glyWord(2), 0.3 + RB, RB); say(glyWord(2).concat(glyWord(2), glyWord(2)), 0.3 + RB * 2, RB * 1.4); }
      if (t > 0.3 + RB * 3.4) { C.ph = 'ignite'; C.t0 = time; C.igFl = false; sfx('hurt', 0.5); }
      return; }
    if (C.ph === 'ignite') { // 몸에 불이 붙음 → 후드가 다 타는 순간 번쩍 · 줄눈에 불씨가 흐르기 시작
      if (!C.igFl && t > IGN.T_END) { C.igFl = true; sfx('blast', 0.6); GR.start(b.x, b.y); }
      if (t > IGN.T_SH) { C.ph = 'p2'; C.cd = 0.8; C.rk = 0; C.rush = null; C.tired = null; b.state = 'chase'; b.maxHp = b.hp = P2_HP * STG().hpMul; b.hpBack = b.hp; C.hpLock = null; lowRoar(); G.fx.push({ kind: 'ring', x: b.x, y: b.y - 24, r: 10, t: 0.8, max: 0.8, c: '#ff7a2a', grow: 520 }); }
      return; }
  }

  function die(b) {
    const C = b.cb; C.ph = 'dead'; C.t0 = time; setMood('cultHall'); // v3.83 처치하면 교단 성가로 b.hp = 0; C.dash = null; C.mv = null; cancelTele(b); b.state = 'dead';
    lowRoar(); ASH.start(b); GR.end(); sfx('blast', 0.5); // v3.60 검은 재로 타올라 바닥에 내려앉음 · 바닥 줄눈 불씨도 사그라듦
    setTimeout(() => { if (B !== b) return; b.dead = true; const R = vault(); if (R) R.ru.cbDone = true; banner('불꽃 비늘 교주 처치', '비늘의 불이 꺼졌습니다', false, b.x); sfx('victory'); }, 1600);
  }

  // ---------------------------------------------------------------- 매 프레임
  function update(e, dt) {
    const C = e.cb; e.flash = Math.max(0, e.flash - dt); e.camK = 0.2;
    if (C.hpLock != null && C.ph !== 'p1' && C.ph !== 'p2') e.hp = C.hpLock;                        // 쓰러짐 · 죽어감 · 멈춤 · 일어섬 · 변신: 피해를 받지 않음
    if (C.ph === 'p1') { if (e.hp <= 1) { fall(e); return; } fight(e, dt); return; }
    if (C.ph === 'fall' || C.ph === 'dying' || C.ph === 'still' || C.ph === 'rise' || C.ph === 'ignite') { fallTick(e, dt); return; }
    if (C.ph === 'p2' && C.rush) e.hp = Math.max(e.hp, C.floor); // 몰아치는 동안은 다음 구간을 넘지 못함
    if (C.ph === 'p2') { GR.setK(C.rush ? 1.9 : C.tired ? 0.25 : 1); fight(e, dt); if (C.tired) { if (Math.random() < dt * 8) G.parts.push({ x: e.x + rand(-10, 10), y: e.y - rand(20, 44), vx: rand(-6, 6), vy: -rand(14, 30), t: rand(0.8, 1.4), c: pick(['#3a3236', '#4a4246', '#5a5258']), g: 0 }); return; } if (C.rush && Math.random() < dt * 40) G.parts.push({ x: e.x + rand(-18, 18), y: e.y - rand(4, 56), vx: rand(-10, 10), vy: -rand(60, 120), t: rand(0.3, 0.6), c: pick(['#fff0be', '#ffcc66', '#ff7a2a']), g: 0, glow: true }); if (Math.random() < dt * 10) G.parts.push({ x: e.x + rand(-12, 12), y: e.y - rand(10, 44), vx: rand(-6, 6), vy: -rand(30, 60), t: rand(0.3, 0.6), c: pick(['#ffcc66', '#ff7a2a', '#d0402a']), g: 0, glow: true }); }
  }
  function barMarks() { // 체력 막대 눈금: 1페이즈 없음 · 2페이즈 75 / 50 / 25
    const bar = $('bossbar'); if (!bar) return; const on = B && G.boss === B && !B.dead, want = on ? (B.cb.ph === 'p2' ? [75, 50, 25] : []) : null, key = want ? want.join(',') || 'none' : 'orig';
    if (bar.dataset.cbk === key) return; bar.dataset.cbk = key; bar.querySelectorAll('.cbmk').forEach(m => m.remove()); bar.querySelectorAll('.mk').forEach(m => { m.style.display = want ? 'none' : ''; });
    if (want) for (const v of want) { const m = document.createElement('span'); m.className = 'mk cbmk'; m.style.left = v + '%'; bar.appendChild(m); } }
  function tick(dt) {
    barMarks(); const R = vault();
    if (!R) { if (B && !B.dead) { B = null; } BUBS.length = 0; return; }
    if (R.ru.cb && R.ru.cb.ph === 'talk' && B && !G.enemies.includes(B) && !CDLG.on && R.ru.cb.done && time - R.ru.cb.done > 0.25) { R.ru.cb.ph = 'fight'; begin(); }
    GR.tick(dt); ASH.tick(dt);
    if (B && !B.dead && G.enemies.includes(B) && G.player) G.player.y = Math.min(G.player.y, A.y1 - G.player.r - 24); // 싸우는 동안 아래 계단(출구)으로 나가지 못함
    { const el = $('boss'); if (el) { const sy = B && G.boss === B && !B.dead ? B.y - CAMY : 999, sx = B ? B.x - CAMX : 0, over = sy > 0 && sy - 70 < 125 && sx > VW * 0.25 && sx < VW * 0.75; const op = over ? '0.3' : ''; if (el.style.opacity !== op) el.style.opacity = op; } } // 교주가 체력 막대 밑에 있으면 막대를 흐리게
    for (let i = BLOOD.length - 1; i >= 0; i--) if (time - BLOOD[i].t0 > 40) BLOOD.splice(i, 1);
    for (let i = BUBS.length - 1; i >= 0; i--) if (time > BUBS[i].t0 + BUBS[i].dur) BUBS.splice(i, 1);
  }

